    "⚠️ Bạn đã hết lượt chat trong tháng này. Vui lòng nâng cấp gói để tiếp tục.": "⚠️ 今月のチャット回数を使い切りました。続けるにはプランをアップグレードしてください。",
    "⚠️ Bắt buộc phải có ghi chú để AI hiểu file của bạn!": "⚠️ AI がファイルを理解できるよう、メモの入力が必須です!",
