    "Để trống + trạng thái \"Đã lên lịch\" = tự động xếp vào khung giờ gần nhất theo luật ở tab \"Lịch đăng bài\".": "Vacío + estado «Programado» = se coloca automáticamente en el hueco más cercano según la regla de la pestaña «Calendario de publicación».",
    "Đọc trả lời bằng giọng nói (TTS)": "Leer las respuestas en voz alta (TTS)",
