    "để bot gửi nút chia sẻ số điện thoại. Trang này tự cập nhật ngay khi bạn xác minh xong, không cần bấm gì thêm ở đây.": "para que el bot envíe el botón de compartir teléfono. Esta página se actualiza sola cuando termines de verificar; no hace falta pulsar nada más aquí.",
    "để nhận báo cáo hằng ngày.": "para recibir el informe diario.",
    "Ưu tiên impression cao, CTR thấp hoặc vị trí 4–20": "Prioriza impresiones altas, CTR bajo o posición 4–20",
