    "ở cuối, đúng như code đang ghép chuỗi.": "al final, tal como el código concatena la cadena.",
    "ở trên (hoặc tự nghĩ 1 chuỗi bất kỳ), rồi bấm": "arriba (o inventa tú cualquier cadena) y luego haz clic en",
    "— chat trực tiếp tại đây, hoặc thêm Telegram chat id ở": "— chatea directamente aquí o añade un Telegram chat id en",
    "— đây là Cloudflare secret, tôi chưa từng thấy giá trị cũ nên không điền sẵn được. Nhớ có dấu": "— es un secret de Cloudflare; nunca he visto el valor anterior, así que no puedo rellenarlo. Recuerda el signo",
    "→ Ad accounts → chọn các tài khoản cần theo dõi, quyền": "→ Ad accounts → elige las cuentas a seguir, permiso",
    "→ Add (vai trò Admin hoặc Employee).": "→ Add (rol Admin o Employee).",
    "⚠️ Bạn đã hết lượt chat trong tháng này. Vui lòng nâng cấp gói để tiếp tục.": "⚠️ Has agotado los chats de este mes. Mejora tu plan para continuar.",
    "⚠️ Bắt buộc phải có ghi chú để AI hiểu file của bạn!": "⚠️ ¡Es obligatorio añadir una nota para que la IA entienda tu archivo!",
