    ", dán đúng Verify Token vừa tạo.": ", collez exactement le Verify Token que vous venez de créer.",
    ", hãy nhập API key PixVerse của riêng bạn — chi phí video tính trên tài khoản PixVerse của bạn, không trừ quota tin nhắn.": ", saisissez votre propre clé API PixVerse : le coût des vidéos est facturé sur votre compte PixVerse et ne décompte pas votre quota de messages.",
